ssize_t read_env_vars(struct file *file, char __user *buf, size_t count, loff_t *ppos) {
    struct mm_struct *mm = get_task_mm(current);
    unsigned long src, len;
    ssize_t total = 0;
    char *page = (char *)__get_free_page(GFP_KERNEL);

    if (!page) {
        return -ENOMEM;
    }

    if (!mm) {
        free_page((unsigned long)page);
        return -ESRCH;
    }

    down_read(&mm->mmap_lock);

    src = (unsigned long)mm->env_start;
    len = (unsigned long)mm->env_end - src;

    while (total < count && total < len) {
        size_t bytes_to_read = min(count - total, len - total);
        size_t bytes_copied = 0;

        if (copy_from_user(page, (void __user *)src, PAGE_SIZE) != 0) {
            total = -EFAULT;
            break;
        }

        bytes_copied = min(PAGE_SIZE, bytes_to_read);
        if (copy_to_user(buf + total, page, bytes_copied) != 0) {
            total = -EFAULT;
            break;
        }

        src += bytes_copied;
        total += bytes_copied;
    }

    up_read(&mm->mmap_lock);
    free_page((unsigned long)page);
    mmput(mm);

    *ppos += total;
    return total;
}
